+
+func newTransferLedger(t *testing.T) *ledger.Ledger {
+	t.Helper()
+	l := ledger.New()
+	a := account.New("a", "al", 1000)
+	a.OverdraftLimit = 100
+	b := account.New("b", "bo", 50)
+	for _, acc := range []*account.Account{a, b} {
+		if err := l.Open(acc); err != nil {
+			t.Fatal(err)
+		}
+	}
+	return l
+}
+
+func TestTransferSuccessHistory(t *testing.T) {
+	l := newTransferLedger(t)
+	if err := l.Transfer("a", "b", 300, "rent"); err != nil {
+		t.Fatal(err)
+	}
+	a, _ := l.Get("a")
+	b, _ := l.Get("b")
+	if a.Balance != 700 || b.Balance != 350 {
+		t.Fatalf("balances = %d, %d; want 700, 350", a.Balance, b.Balance)
+	}
+	wantA := []account.Entry{{Kind: "transfer-out", Amount: -300, Memo: "rent", BalanceAfter: 700, Counterparty: "b"}}
+	wantB := []account.Entry{{Kind: "transfer-in", Amount: 300, Memo: "rent", BalanceAfter: 350, Counterparty: "a"}}
+	if !reflect.DeepEqual(a.History, wantA) {
+		t.Fatalf("a.History = %+v, want %+v", a.History, wantA)
+	}
+	if !reflect.DeepEqual(b.History, wantB) {
+		t.Fatalf("b.History = %+v, want %+v", b.History, wantB)
+	}
+}
+
+func TestTransferErrorOrder(t *testing.T) {
+	cases := []struct {
+		name     string
+		from, to string
+		cents    int64
+		want     error
+	}{
+		{"zero amount", "a", "b", 0, ledger.ErrInvalidAmount},
+		{"same account unknown id", "x", "x", 5, ledger.ErrSameAccount},
+		{"same account", "a", "a", 5, ledger.ErrSameAccount},
+		{"unknown source", "x", "b", 5, ledger.ErrUnknownAccount},
+		{"unknown destination", "a", "x", 5, ledger.ErrUnknownAccount},
+		{"overdraft past limit", "a", "b", 1101, ledger.ErrInsufficientFunds},
+		{"invalid amount beats unknown", "x", "b", -1, ledger.ErrInvalidAmount},
+	}
+	for _, c := range cases {
+		t.Run(c.name, func(t *testing.T) {
+			l := newTransferLedger(t)
+			err := l.Transfer(c.from, c.to, c.cents, "")
+			if !errors.Is(err, c.want) {
+				t.Fatalf("err = %v, want %v", err, c.want)
+			}
+			a, _ := l.Get("a")
+			b, _ := l.Get("b")
+			if a.Balance != 1000 || b.Balance != 50 || len(a.History) != 0 || len(b.History) != 0 {
+				t.Fatalf("failed transfer changed state: a=%+v b=%+v", a, b)
+			}
+		})
+	}
+}
+
+func TestTransferExactOverdraftAllowed(t *testing.T) {
+	l := newTransferLedger(t)
+	if err := l.Transfer("a", "b", 1100, ""); err != nil {
+		t.Fatalf("transfer to exactly -OverdraftLimit: %v", err)
+	}
+	a, _ := l.Get("a")
+	if a.Balance != -100 {
+		t.Fatalf("a.Balance = %d, want -100", a.Balance)
+	}
+}

