+#[test]
+fn workload_of_sweeping_inserts_and_removes_is_fast_and_canonical() {
+    let mut rng = Lcg(12345);
+    let mut s = IntervalSet::new();
+    let start = Instant::now();
+    for i in 0..300_000i64 {
+        let base = 1_000_000_000 - i * 3_333;
+        let lo = base + rng.below(1001) as i64 - 500;
+        let hi = lo + rng.below(1001) as i64;
+        s.insert(closed_or_open(&mut rng, lo), closed_or_open(&mut rng, hi));
+
+        let rlo = base + rng.below(1001) as i64 - 500;
+        let rhi = rlo + rng.below(1001) as i64;
+        s.remove(closed_or_open(&mut rng, rlo), closed_or_open(&mut rng, rhi));
+
+        let x = rng.below(1_000_000_001) as f64;
+        let _ = s.contains(x);
+    }
+    let elapsed = start.elapsed();
+    assert!(
+        elapsed.as_secs_f64() < 3.0,
+        "workload took {:?}",
+        elapsed
+    );
+
+    let ranges = s.ranges();
+    for pair in ranges.windows(2) {
+        let (a_lo, a_hi) = pair[0];
+        let (b_lo, b_hi) = pair[1];
+        assert!(a_lo.value() <= a_hi.value());
+        assert!(b_lo.value() <= b_hi.value());
+        let separate = a_hi.value() < b_lo.value()
+            || (a_hi.value() == b_lo.value() && !a_hi.is_closed() && !b_lo.is_closed());
+        assert!(separate, "mergeable neighbours {:?} {:?}", pair[0], pair[1]);
+    }
+}

