+use shapekit::{Shape, ShapeError};
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
+
+#[test]
+fn parse_accepts_each_kind_case_insensitively() {
+    assert_eq!(Shape::parse("circle", &[2.0]), Ok(Shape::Circle { r: 2.0 }));
+    assert_eq!(Shape::parse("CiRcLe", &[2.0]), Ok(Shape::Circle { r: 2.0 }));
+    assert_eq!(Shape::parse("rect", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(Shape::parse("RECTANGLE", &[2.0, 3.0]), Ok(Shape::Rect { w: 2.0, h: 3.0 }));
+    assert_eq!(Shape::parse("Square", &[4.0]), Ok(Shape::Rect { w: 4.0, h: 4.0 }));
+    assert_eq!(
+        Shape::parse("TrIaNgLe", &[3.0, 4.0, 5.0]),
+        Ok(Shape::Triangle { a: 3.0, b: 4.0, c: 5.0 })
+    );
+    assert_ne!(Shape::parse("circle", &[2.0]), Ok(Shape::Rect { w: 2.0, h: 2.0 }));
+}
+
+#[test]
+fn parse_reports_unknown_kind_with_original_spelling() {
+    assert_eq!(
+        Shape::parse("HeXa", &[1.0]),
+        Err(ShapeError::UnknownKind("HeXa".to_string()))
+    );
+    assert_ne!(Shape::parse("circle", &[1.0]), Err(ShapeError::UnknownKind("circle".to_string())));
+}
+
+#[test]
+fn parse_checks_kind_before_count_then_sign_then_triangle() {
+    assert_eq!(
+        Shape::parse("hexagon", &[1.0, 2.0]),
+        Err(ShapeError::UnknownKind("hexagon".to_string()))
+    );
+    assert_eq!(
+        Shape::parse("circle", &[1.0, 2.0]),
+        Err(ShapeError::WrongParamCount { expected: 1, got: 2 })
+    );
+    assert_eq!(
+        Shape::parse("rect", &[1.0]),
+        Err(ShapeError::WrongParamCount { expected: 2, got: 1 })
+    );
+    assert_eq!(Shape::parse("circle", &[-1.0]), Err(ShapeError::NegativeDimension));
+    assert_eq!(
+        Shape::parse("triangle", &[-1.0, 1.0, 1.0]),
+        Err(ShapeError::NegativeDimension)
+    );
+    assert_eq!(
+        Shape::parse("triangle", &[1.0, 1.0, 5.0]),
+        Err(ShapeError::InvalidTriangle)
+    );
+}
+
+#[test]
+fn parse_allows_zero_and_degenerate_triangles() {
+    assert_eq!(Shape::parse("rect", &[0.0, 0.0]), Ok(Shape::Rect { w: 0.0, h: 0.0 }));
+    assert_eq!(
+        Shape::parse("triangle", &[1.0, 2.0, 3.0]),
+        Ok(Shape::Triangle { a: 1.0, b: 2.0, c: 3.0 })
