+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
+
+#[test]
+fn summary_reports_interpolated_p50_and_p90() {
+    assert_eq!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_is_independent_of_input_order() {
+    assert_eq!(summary(&[3.0, 1.0, 4.0, 2.0]), summary(&[1.0, 2.0, 3.0, 4.0]));
+    assert_ne!(summary(&[4.0, 3.0, 2.0, 1.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_of_empty_input_is_just_count() {
+    assert_eq!(summary(&[]), "n=0");
+    assert_ne!(summary(&[]), "n=0 mean=NaN p50=0.00 p90=0.00");
+}
+
+#[test]
+fn summary_ignores_nan_values() {
+    assert_eq!(summary(&[1.0, f64::NAN, 3.0]), "n=2 mean=2.00 p50=2.00 p90=2.80");
+    assert_eq!(summary(&[f64::NAN, f64::NAN]), "n=0");
+    assert_ne!(summary(&[1.0, f64::NAN, 3.0]), "n=3 mean=NaN p50=2.00 p90=2.80");
+}
+
+#[test]
+fn count_counts_only_non_nan_values() {
+    assert_eq!(count(&[1.0, f64::NAN, 3.0]), 2);
+    assert_eq!(count(&[f64::NAN]), 0);
+    assert_ne!(count(&[1.0, f64::NAN, 3.0]), 3);
+}
+
+#[test]
+fn mean_is_none_without_non_nan_values() {
+    assert_eq!(mean(&[]), None);
+    assert_eq!(mean(&[f64::NAN, f64::NAN]), None);
+    let m = mean(&[1.0, f64::NAN, 2.0, 3.0, 4.0]).unwrap();
+    assert!(close(m, 2.5));
+    assert!(!m.is_nan());
+}
+
+#[test]
+fn median_is_none_without_non_nan_values() {
+    assert_eq!(median(&[]), None);
+    assert_eq!(median(&[f64::NAN]), None);
+    let m = median(&[1.0, 2.0, 3.0, 4.0]).unwrap();
+    assert!(close(m, 2.5));
+    assert!(!close(m, 2.0));
+    let n = median(&[f64::NAN, 5.0, 1.0, 3.0]).unwrap();
+    assert!(close(n, 3.0));
+}
+
+#[test]
+fn percentile_rejects_nan_and_out_of_range_p() {
+    let v = [1.0, 2.0, 3.0, 4.0];
