+use stockkit::{Inventory, Order, ReserveError};
+
+#[test]
+fn quantities_by_sku_sums_sorts_and_drops_zero() {
+    let order = Order::new("o")
+        .with_line("pear", 2)
+        .with_line("apple", 1)
+        .with_line("pear", 3)
+        .with_line("fig", 0);
+    assert_eq!(
+        order.quantities_by_sku(),
+        vec![("apple".to_string(), 1), ("pear".to_string(), 5)]
+    );
+}
+
+#[test]
+fn reserve_reduces_available_but_not_on_hand() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 3)).unwrap();
+    assert_eq!(inv.available("apple"), 2);
+    assert_eq!(inv.on_hand("apple"), 5);
+    inv.release(id).unwrap();
+    assert_eq!(inv.available("apple"), 5);
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn commit_drops_on_hand_and_keeps_available() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 3)).unwrap();
+    let before = inv.available("apple");
+    inv.commit(id).unwrap();
+    assert_eq!(inv.on_hand("apple"), 2);
+    assert_eq!(inv.available("apple"), before);
+    assert_eq!(inv.commit(id), Err(ReserveError::UnknownReservation));
+}
+
+#[test]
+fn reserve_is_all_or_nothing_in_sku_order() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 1);
+    inv.add_stock("pear", 1);
+    let order = Order::new("o").with_line("pear", 5).with_line("apple", 2);
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::Insufficient {
+            sku: "apple".to_string(),
+            requested: 2,
+            available: 1,
+        })
+    );
+    assert_eq!(inv.available("pear"), 1);
+    let unknown_first = Order::new("o").with_line("aardvark", 1).with_line("apple", 9);
+    assert_eq!(
+        inv.reserve(&unknown_first),
+        Err(ReserveError::UnknownSku("aardvark".to_string()))
+    );
+}
+
+#[test]
+fn reservation_ids_are_not_reused() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 2);
+    let a = inv.reserve(&Order::new("a")).unwrap();
+    let b = inv.reserve(&Order::new("b")).unwrap();
+    assert_ne!(a, b);
+    inv.release(a).unwrap();
+    let c = inv.reserve(&Order::new("c")).unwrap();
+    assert_ne!(c, a);
+    assert_ne!(c, b);
+}

