diff --git a/test/cron.test.ts b/test/cron.test.ts
new file mode 100644
index 0000000..e721b94
--- /dev/null
+++ b/test/cron.test.ts
@@ -0,0 +1,91 @@
+import { expect, test } from "bun:test";
+import { CronError, nextRun } from "../src/cron";
+
+const at = (iso: string) => new Date(iso);
+
+test("steps and lists in minutes", () => {
+  expect(nextRun("*/15 * * * *", at("2024-01-01T10:07:30Z")).toISOString()).toBe("2024-01-01T10:15:00.000Z");
+  expect(nextRun("10-50/20 * * * *", at("2024-01-01T10:10:00Z")).toISOString()).toBe("2024-01-01T10:30:00.000Z");
+});
+
+test("does not modify from and drops seconds", () => {
+  const from = at("2024-01-01T10:00:45.500Z");
+  const next = nextRun("* * * * *", from);
+  expect(next.toISOString()).toBe("2024-01-01T10:01:00.000Z");
+  expect(from.toISOString()).toBe("2024-01-01T10:00:45.500Z");
+});
+
+test("classic day rule: OR when both day fields restricted", () => {
+  // last day of Feb 2024 is Thursday the 29th; first Monday is the 5th
+  expect(nextRun("0 0 L * 1", at("2024-02-01T00:00:00Z")).toISOString()).toBe("2024-02-05T00:00:00.000Z");
+});
+
+test("classic day rule: only the restricted field counts when the other is *", () => {
+  expect(nextRun("0 0 * 2 5L", at("2024-01-01T00:00:00Z")).toISOString()).toBe("2024-02-23T00:00:00.000Z");
+  expect(nextRun("0 0 * * 5#3", at("2024-01-01T00:00:00Z")).toISOString()).toBe("2024-01-19T00:00:00.000Z");
+});
+
+test("nW and LW specials", () => {
+  // June 1 2024 is a Saturday -> Monday June 3
+  expect(nextRun("0 0 1W 6 *", at("2024-01-01T00:00:00Z")).toISOString()).toBe("2024-06-03T00:00:00.000Z");
+  expect(nextRun("0 0 LW 2 *", at("2024-01-01T00:00:00Z")).toISOString()).toBe("2024-02-29T00:00:00.000Z");
+});
+
+test("Feb 29 and nonexistent days", () => {
+  expect(nextRun("0 0 29 2 *", at("2025-01-01T00:00:00Z")).toISOString()).toBe("2028-02-29T00:00:00.000Z");
+  expect(() => nextRun("0 0 30 2 *", at("2024-01-01T00:00:00Z"))).toThrow(CronError);
+});
+
+test("aliases are case-insensitive and strict", () => {
+  expect(nextRun("@DAILY", at("2024-01-01T10:00:00Z")).toISOString()).toBe("2024-01-02T00:00:00.000Z");
+  expect(() => nextRun("@daily 5", at("2024-01-01T00:00:00Z"))).toThrow(CronError);
+  expect(() => nextRun("@sometimes", at("2024-01-01T00:00:00Z"))).toThrow(CronError);
+});
+
+test("names in month and day-of-week", () => {
+  expect(nextRun("0 0 1 jan,Jul *", at("2024-02-01T00:00:00Z")).toISOString()).toBe("2024-07-01T00:00:00.000Z");
+  expect(nextRun("0 0 * * MON-FRI", at("2024-01-06T00:00:00Z")).toISOString()).toBe("2024-01-08T00:00:00.000Z");
+});
+
+test("invalid expressions throw CronError", () => {
+  const bad = [
+    "* * * *",
+    "60 * * * *",
+    "5/15 * * * *",
+    "*/0 * * * *",
+    "5-1 * * * *",
+    "1,,2 * * * *",
+    "0 0 * * 8",
+    "0 0 * JANX *",
+    "0 0 * * L",
+    "0 0 1-5W * *",
+    "0 0 * * 5W",
+    "0 0 L/2 * *",
+    "0 0 * * 8#1",
+    "0 0 * * 5#0",
+    "0 0 * * 5#6",
+    "0 0 * * 5L/2",
+    "0 0 * * * *",
+  ];
+  for (const expr of bad) {
+    expect(() => nextRun(expr, at("2024-01-01T00:00:00Z"))).toThrow(CronError);
+  }
+});
+
+test("rare schedules average well under 1 ms per call", () => {
+  const exprs = ["0 0 29 2 1", "59 23 31 12 5L", "0 0 LW 2 *", "30 4 15W * 1#5", "0 0 29 2 *"];
+  const started = performance.now();
+  let calls = 0;
+  for (let i = 0; i < 3000; i++) {
+    const year = 2000 + (i % 100);
+    const from = new Date(Date.UTC(year, i % 12, 1 + (i % 28), i % 24, i % 60));
+    try {
+      nextRun(exprs[i % exprs.length], from);
+    } catch (e) {
+      if (!(e instanceof CronError)) throw e;
+    }
+    calls++;
+  }
+  expect(calls).toBe(3000);
+  expect(performance.now() - started).toBeLessThan(2000);
+});

