@@ -0,0 +1,88 @@
+use intervalkit::{Bound, IntervalSet};
+
+#[test]
+fn merges_touching_and_keeps_missing_points_apart() {
+    let mut a = IntervalSet::new();
+    a.insert(Bound::Closed(1), Bound::Open(3));
+    a.insert(Bound::Closed(3), Bound::Closed(5));
+    assert_eq!(a.ranges(), vec![(Bound::Closed(1), Bound::Closed(5))]);
+
+    let mut b = IntervalSet::new();
+    b.insert(Bound::Open(1), Bound::Open(3));
+    b.insert(Bound::Open(3), Bound::Open(5));
+    assert_eq!(
+        b.ranges(),
+        vec![
+            (Bound::Open(1), Bound::Open(3)),
+            (Bound::Open(3), Bound::Open(5))
+        ]
+    );
+    assert_eq!(b.to_string(), "{(1,3), (3,5)}");
+}
+
+#[test]
+fn remove_splits_intervals() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(1), Bound::Closed(5));
+    s.remove(Bound::Closed(2), Bound::Closed(2));
+    assert_eq!(s.to_string(), "{[1,2), (2,5]}");
+    let mut t = IntervalSet::new();
+    t.insert(Bound::Closed(1), Bound::Closed(5));
+    t.remove(Bound::Open(2), Bound::Open(4));
+    assert_eq!(t.to_string(), "{[1,2], [4,5]}");
+}
+
+#[test]
+fn complement_flips_endpoints() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(2), Bound::Open(4));
+    s.insert(Bound::Open(6), Bound::Closed(8));
+    assert_eq!(
+        s.complement(Bound::Closed(0), Bound::Closed(10)),
+        vec![
+            (Bound::Closed(0), Bound::Open(2)),
+            (Bound::Closed(4), Bound::Closed(6)),
+            (Bound::Open(8), Bound::Closed(10)),
+        ]
+    );
+    assert!(s.complement(Bound::Closed(3), Bound::Open(3)).is_empty());
+}
+
+#[test]
+fn extreme_values_do_not_overflow() {
+    let mut s = IntervalSet::new();
+    s.insert(Bound::Closed(i64::MIN), Bound::Closed(i64::MAX));
+    assert_eq!(s.measure(), i64::MAX as i128 - i64::MIN as i128);
+    assert!(s.contains(i64::MIN as f64));
+    s.remove(Bound::Open(i64::MIN), Bound::Open(i64::MAX));
+    assert_eq!(
+        s.ranges(),
+        vec![
+            (Bound::Closed(i64::MIN), Bound::Closed(i64::MIN)),
+            (Bound::Closed(i64::MAX), Bound::Closed(i64::MAX)),
+        ]
+    );
+}
+
+#[test]
+fn large_workload_is_fast() {
+    let mut s = IntervalSet::new();
+    let mut seed: u64 = 0x2545_F491_4F6C_DD1D;
+    let mut next = move || {
+        seed ^= seed << 13;
+        seed ^= seed >> 7;
+        seed ^= seed << 17;
+        seed
+    };
+    for i in 0..300_000i64 {
+        let jitter = (next() % 500) as i64;
+        let base = 1_000_000_000 - i * 3333 + jitter;
+        let len = (next() % 1001) as i64;
+        s.insert(Bound::Closed(base), Bound::Closed(base + len));
+        if i % 2 == 0 {
+            s.remove(Bound::Closed(base), Bound::Closed(base + len / 2));
+        }
+        let x = (next() % 1_000_000_001) as f64;
+        let _ = s.contains(x);
+    }
+}

