+use std::collections::HashSet;
+
+use romankit::roman::{from_roman, to_roman, RomanError};
+
+fn canonical_of(n: u32) -> String {
+    to_roman(n).ok().expect("valid n must render")
+}
+
+#[test]
+fn to_roman_rejects_out_of_range() {
+    assert!(matches!(to_roman(0), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(4000), Err(RomanError::OutOfRange)));
+    assert!(matches!(to_roman(u32::MAX), Err(RomanError::OutOfRange)));
+    assert_eq!(to_roman(1).ok(), Some("I".to_string()));
+    assert_eq!(to_roman(3999).ok(), Some("MMMCMXCIX".to_string()));
+}
+
+#[test]
+fn to_roman_renders_canonical_forms() {
+    assert_eq!(to_roman(4).ok(), Some("IV".to_string()));
+    assert_eq!(to_roman(19).ok(), Some("XIX".to_string()));
+    assert_eq!(to_roman(1994).ok(), Some("MCMXCIV".to_string()));
+    assert!(to_roman(4).ok() != Some("IIII".to_string()));
+}
+
+#[test]
+fn from_roman_parses_subtractive_endings() {
+    assert_eq!(from_roman("IV").ok(), Some(4));
+    assert_eq!(from_roman("XIX").ok(), Some(19));
+    assert_eq!(from_roman("MCMXCIV").ok(), Some(1994));
+    assert!(from_roman("IV").ok() != Some(6));
+    assert!(from_roman("XIX").ok() != Some(21));
+}
+
+#[test]
+fn round_trip_covers_full_range() {
+    for n in 1..=3999u32 {
+        let s = canonical_of(n);
+        assert_eq!(from_roman(&s).ok(), Some(n), "round trip failed for {n}");
+    }
+}
+
+#[test]
+fn from_roman_rejects_empty() {
+    assert!(matches!(from_roman(""), Err(RomanError::Empty)));
+    assert!(from_roman("").ok() != Some(0));
+}
+
+#[test]
+fn from_roman_reports_first_invalid_char() {
+    assert!(matches!(from_roman("xiv"), Err(RomanError::InvalidChar('x'))));
+    assert!(matches!(from_roman("IV "), Err(RomanError::InvalidChar(' '))));
+    assert!(matches!(from_roman("I V"), Err(RomanError::InvalidChar(' '))));
+    assert!(matches!(from_roman("abcX"), Err(RomanError::InvalidChar('a'))));
+    assert!(matches!(from_roman("MMMMx"), Err(RomanError::InvalidChar('x'))));
+}
+
+#[test]
+fn from_roman_rejects_non_canonical() {
+    for s in ["IIII", "IC", "VX", "MMMM", "IIV", "XM"] {
+        assert!(
+            matches!(from_roman(s), Err(RomanError::NonCanonical)),
+            "expected NonCanonical for {s:?}"
+        );
+    }
+}
+
+#[test]
+fn from_roman_accepts_exactly_canonical_strings() {
+    let letters = ['I', 'V', 'X', 'L', 'C', 'D', 'M'];
+    let mut canon: HashSet<String> = HashSet::new();
+    for n in 1..=3999u32 {
+        canon.insert(canonical_of(n));
+    }
+
+    let mut candidates: Vec<String> = vec![String::new()];
+    let mut frontier: Vec<String> = vec![String::new()];
+    for _ in 0..4 {
+        let mut next = Vec::new();
+        for prefix in &frontier {
+            for &c in &letters {
+                let mut s = prefix.clone();
+                s.push(c);
+                next.push(s);
+            }
+        }
+        candidates.extend(next.iter().cloned());
+        frontier = next;
+    }
+
+    for s in &candidates {
+        match from_roman(s) {
+            Ok(n) => {
+                assert!((1..=3999).contains(&n), "{s:?} gave out-of-range {n}");
+                assert_eq!(canonical_of(n), *s, "{s:?} accepted but not canonical");
+            }
+            Err(e) => {
+                assert!(!matches!(e, RomanError::OutOfRange), "{s:?} gave OutOfRange");
+                assert!(!canon.contains(s), "canonical {s:?} rejected");
+            }
+        }
+    }
+}
