+use statkit::stats::{count, mean, median, percentile};
+use statkit::summary;
+
+fn close(a: f64, b: f64) -> bool {
+    (a - b).abs() < 1e-9
+}
+
+#[test]
+fn summary_matches_expected_report_for_sorted_input() {
+    assert_eq!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[1.0, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_is_independent_of_input_order() {
+    assert_eq!(summary(&[4.0, 1.0, 3.0, 2.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert_ne!(summary(&[4.0, 1.0, 3.0, 2.0]), "n=4 mean=2.50 p50=2.00 p90=3.00");
+}
+
+#[test]
+fn summary_of_empty_input_is_just_count() {
+    assert_eq!(summary(&[]), "n=0");
+    assert_ne!(summary(&[]), "n=0 mean=NaN p50=0.00 p90=0.00");
+}
+
+#[test]
+fn summary_of_all_nan_input_is_just_count() {
+    assert_eq!(summary(&[f64::NAN, f64::NAN]), "n=0");
+    assert_ne!(summary(&[f64::NAN]), "n=1 mean=NaN p50=NaN p90=NaN");
+}
+
+#[test]
+fn summary_ignores_nan_values() {
+    assert_eq!(summary(&[1.0, f64::NAN, 2.0, 3.0, 4.0]), "n=4 mean=2.50 p50=2.50 p90=3.70");
+    assert!(!summary(&[1.0, f64::NAN, 3.0]).contains("NaN"));
+}
+
+#[test]
+fn count_ignores_nan_values() {
+    assert_eq!(count(&[1.0, f64::NAN, 3.0]), 2);
+    assert_ne!(count(&[1.0, f64::NAN, 3.0]), 3);
+    assert_eq!(count(&[f64::NAN]), 0);
+    assert_eq!(count(&[]), 0);
+}
+
+#[test]
+fn mean_ignores_nan_and_is_none_when_undefined() {
+    assert!(close(mean(&[1.0, f64::NAN, 3.0]).unwrap(), 2.0));
+    assert!(!mean(&[1.0, f64::NAN, 3.0]).unwrap().is_nan());
+    assert_eq!(mean(&[]), None);
+    assert_eq!(mean(&[f64::NAN, f64::NAN]), None);
+}
+
+#[test]
+fn median_is_percentile_fifty_and_none_when_undefined() {
+    assert!(close(median(&[1.0, 2.0, 3.0, 4.0]).unwrap(), 2.5));
+    assert!(close(median(&[4.0, 1.0, 3.0, 2.0]).unwrap(), 2.5));
+    assert!(close(median(&[1.0, f64::NAN, 3.0]).unwrap(), 2.0));
+    assert_ne!(median(&[1.0, 2.0, 3.0, 4.0]).unwrap(), 2.0);
+    assert_eq!(median(&[]), None);
+    assert_eq!(median(&[f64::NAN]), None);
+}
+
+#[test]
+fn percentile_interpolates_between_closest_ranks() {
+    assert!(close(percentile(&[1.0, 2.0, 3.0, 4.0], 90.0).unwrap(), 3.7));
+    assert!(close(percentile(&[4.0, 3.0, 2.0, 1.0], 90.0).unwrap(), 3.7));
+    assert!(!close(percentile(&[1.0, 2.0, 3.0, 4.0], 90.0).unwrap(), 3.0));
+}
+
+#[test]
+fn percentile_endpoints_are_min_and_max() {
+    let v = [3.0, 9.0, 1.0, 7.0];
+    assert!(close(percentile(&v, 0.0).unwrap(), 1.0));
+    assert!(close(percentile(&v, 100.0).unwrap(), 9.0));
+    assert!(!close(percentile(&v, 100.0).unwrap(), 7.0));
+}
+
+#[test]
+fn percentile_rejects_nan_and_out_of_range_p() {
+    let v = [1.0, 2.0, 3.0];
+    assert_eq!(percentile(&v, f64::NAN), None);
+    assert_eq!(percentile(&v, -0.1), None);
+    assert_eq!(percentile(&v, 100.1), None);
+    assert!(percentile(&v, 100.0).is_some());
+}
+
+#[test]
+fn percentile_is_none_when_no_non_nan_values() {
+    assert_eq!(percentile(&[], 50.0), None);
+    assert_eq!(percentile(&[f64::NAN], 50.0), None);
+}
+
+#[test]
+fn percentile_does_not_modify_input() {
+    let v = vec![4.0, 1.0, f64::NAN, 3.0, 2.0];
+    let before = v.clone();
+    let _ = percentile(&v, 50.0);
+    let _ = median(&v);
+    let _ = mean(&v);
+    let _ = count(&v);
+    assert_eq!(format!("{:?}", v), format!("{:?}", before));
+    assert!(v[2].is_nan());
+    assert_eq!(v[0], 4.0);
+}
