+    inv.add_stock("apple", 5);
+    inv.add_stock("pear", 1);
+    let order = Order::new("o")
+        .with_line("apple", 2)
+        .with_line("pear", 2)
+        .with_line("plum", 1);
+    // "apple" < "pear" < "plum": pear is checked first and fails.
+    assert_eq!(
+        inv.reserve(&order),
+        Err(ReserveError::Insufficient {
+            sku: "pear".to_string(),
+            requested: 2,
+            available: 1,
+        })
+    );
+    assert_eq!(inv.available("apple"), 5);
+
+    let unknown = Order::new("o").with_line("apple", 1).with_line("plum", 1);
+    assert_eq!(
+        inv.reserve(&unknown),
+        Err(ReserveError::UnknownSku("plum".to_string()))
+    );
+    assert_eq!(inv.available("apple"), 5);
+}
+
+#[test]
+fn zero_quantity_order_gets_fresh_empty_reservation() {
+    let mut inv = Inventory::new();
+    let a = inv.reserve(&Order::new("o")).unwrap();
+    let b = inv.reserve(&Order::new("o").with_line("nothing", 0)).unwrap();
+    assert_ne!(a, b);
+    inv.release(a).unwrap();
+    inv.release(b).unwrap();
+}
+
+#[test]
+fn commit_ships_units_and_keeps_available_stable() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 4)).unwrap();
+    let before = inv.available("apple");
+    inv.commit(id).unwrap();
+    assert_eq!(inv.on_hand("apple"), 1);
+    assert_eq!(inv.available("apple"), before);
+}
+
+#[test]
+fn unknown_or_finished_reservations_are_rejected() {
+    let mut inv = Inventory::new();
+    inv.add_stock("apple", 5);
+    let id = inv.reserve(&Order::new("o").with_line("apple", 1)).unwrap();
+    inv.release(id).unwrap();
+    assert_eq!(inv.release(id), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.commit(id), Err(ReserveError::UnknownReservation));
+
+    let id2 = inv.reserve(&Order::new("o").with_line("apple", 1)).unwrap();
+    inv.commit(id2).unwrap();
+    assert_eq!(inv.commit(id2), Err(ReserveError::UnknownReservation));
+    assert_eq!(inv.on_hand("apple"), 4);
+}

